Write a function that Use a timer to stop the subprocess if the timeout is exceeded. This helps prevent very subtle issues with deadlocks on reading subprocess output. See: http://stackoverflow.com/a/10012262

Python function:
def timeout(timeout):
    def decorator(func):
        def wrapper(*args, **kwargs):
            def timeout_handler():
                raise TimeoutError
            old_timeout = signal.signal(signal.SIGALRM, timeout_handler)
            signal.alarm(timeout)
            try:
                return func(*args, **kwargs)
            finally:
                signal.alarm(0)
                signal.signal(signal.SIGALRM, old_timeout)
        return wrapper
    return decorator
